TWComponent.script:
tw.local.results = new tw.object.listOf.NameValuePair();

if(tw.local.countryList != null)
{
	for(var i=0;i<tw.local.countryList.listLength;i++)
	{
		tw.local.results[i]=new tw.object.NameValuePair();
		tw.local.results[i].name=tw.local.countryList[i].value;
		tw.local.results[i].value= tw.local.countryList[i].name;
	}
	

}

tw.local.results = new tw.object.listOf.NameValuePair();

tw.local.results[0]=new tw.object.NameValuePair();
tw.local.results[0].name="EG";
tw.local.results[0].value= "مصر";

tw.local.results[1]=new tw.object.NameValuePair();
tw.local.results[1].name="AU";
tw.local.results[1].value="أستراليا"

